import{_ as s,a as i}from"./chunks/edit_pack.BgW_0E6q.js";import{_ as n,c as e,o as t,ae as l}from"./chunks/framework.BrQRMotl.js";const E=JSON.parse('{"title":"サウンドパックマネージャー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/sound_packs.md","filePath":"ja/manual/sound_packs.md"}'),o={name:"ja/manual/sound_packs.md"};function p(r,a,h,d,c,k){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="サウンドパックマネージャー" tabindex="-1">サウンドパックマネージャー <a class="header-anchor" href="#サウンドパックマネージャー" aria-label="Permalink to &quot;サウンドパックマネージャー&quot;">​</a></h1><p>Extended Note Block のサウンドパックは、本質的に標準的な <strong>Minecraft リソースパック</strong> であるため、共有やインストールが簡単です。この MOD は、作成と切り替えプロセスを簡素化するための組み込みマネージャーを提供します。</p><h2 id="マネージャーを開く" tabindex="-1">マネージャーを開く <a class="header-anchor" href="#マネージャーを開く" aria-label="Permalink to &quot;マネージャーを開く&quot;">​</a></h2><ul><li>ゲーム設定ページで、<code>Sound Packs...</code>（サウンドパック）を見つけて開きます。</li></ul><h2 id="コア機能" tabindex="-1">コア機能 <a class="header-anchor" href="#コア機能" aria-label="Permalink to &quot;コア機能&quot;">​</a></h2><h3 id="_1-閲覧と有効化" tabindex="-1">1. 閲覧と有効化 <a class="header-anchor" href="#_1-閲覧と有効化" aria-label="Permalink to &quot;1. 閲覧と有効化&quot;">​</a></h3><p><img src="'+s+'" alt="SoundPackManager"></p><ul><li>マネージャーは、<code>resourcepacks</code> ディレクトリ内で認識されたすべての Extended Note Block サウンドパックを一覧表示します。</li><li>サウンドパックを選択すると、それが有効になります。これは実際には、Minecraft のリソースパックリストの一番上でそのリソースパックを有効にすることと同じです。</li></ul><h3 id="_2-新しいサウンドパックの作成" tabindex="-1">2. 新しいサウンドパックの作成 <a class="header-anchor" href="#_2-新しいサウンドパックの作成" aria-label="Permalink to &quot;2. 新しいサウンドパックの作成&quot;">​</a></h3><ul><li>「新規 (New)」ボタンをクリックし、名前を入力すると、MOD は <code>.minecraft/resourcepacks/</code> 下に新しいフォルダ構造を自動的に作成します。</li><li>自動生成されるファイルには、<code>pack.mcmeta</code>（リソースパックメタデータ）と <code>pack.json</code>（サウンドパック設定）が含まれます。</li></ul><h3 id="_3-編集と更新" tabindex="-1">3. 編集と更新 <a class="header-anchor" href="#_3-編集と更新" aria-label="Permalink to &quot;3. 編集と更新&quot;">​</a></h3><p><img src="'+i+`" alt="EditPack"></p><ul><li>サウンドパックを通常のフォルダとして直接開いて編集できます。</li><li>ファイルを変更した後、ゲーム内で <strong>「更新 (Refresh)」</strong> をクリックすると、MOD はディレクトリを再スキャンし、<code>sounds.json</code> を更新して、ゲームを再起動せずにリソースをリロードします。</li></ul><h2 id="サウンドパック制作ガイド" tabindex="-1">サウンドパック制作ガイド <a class="header-anchor" href="#サウンドパック制作ガイド" aria-label="Permalink to &quot;サウンドパック制作ガイド&quot;">​</a></h2><p>サウンドパックを手動で作成または変更したい場合は、以下の仕様に従ってください：</p><h3 id="ディレクトリ位置" tabindex="-1">ディレクトリ位置 <a class="header-anchor" href="#ディレクトリ位置" aria-label="Permalink to &quot;ディレクトリ位置&quot;">​</a></h3><p>すべてのサウンドパックは、標準のリソースパックディレクトリに配置されます： <code>.minecraft/resourcepacks/</code></p><h3 id="ファイル構造" tabindex="-1">ファイル構造 <a class="header-anchor" href="#ファイル構造" aria-label="Permalink to &quot;ファイル構造&quot;">​</a></h3><p>標準的なサウンドパックの構造は以下の通りです：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MySoundPack/</span></span>
<span class="line"><span>├── pack.mcmeta          # (必須) 標準 Minecraft リソースパックメタデータ</span></span>
<span class="line"><span>├── pack.json            # (必須) Extended Note Block 専用設定</span></span>
<span class="line"><span>└── assets</span></span>
<span class="line"><span>    └── extendednoteblock</span></span>
<span class="line"><span>        ├── sounds.json  # (自動生成) サウンドイベントを定義、通常は MOD によって自動管理されます</span></span>
<span class="line"><span>        └── sounds</span></span>
<span class="line"><span>            └── notes    # (コア) オーディオファイルをここに配置します</span></span></code></pre></div><h3 id="オーディオファイル仕様" tabindex="-1">オーディオファイル仕様 <a class="header-anchor" href="#オーディオファイル仕様" aria-label="Permalink to &quot;オーディオファイル仕様&quot;">​</a></h3><ol><li><strong>形式</strong>: <strong><code>.ogg</code></strong> 形式 (Vorbis エンコーディング) である必要があります。<code>.wav</code> や <code>.mp3</code> はサポートされていません。</li><li><strong>命名</strong>: ファイル名は <code>楽器ID.音符ID.ogg</code> の形式に従う必要があります。 <ul><li><strong>楽器ID</strong>: MOD 内の楽器番号に対応します（例：0 はハープ/ピアノ）。</li><li><strong>音符ID</strong>: MIDI 音程番号 (0-127)。</li><li>例: <code>0.60.ogg</code> は楽器 0 (ピアノ) の中央 C (ド) を表します。</li></ul></li></ol><h3 id="設定ファイル-pack-json" tabindex="-1">設定ファイル (pack.json) <a class="header-anchor" href="#設定ファイル-pack-json" aria-label="Permalink to &quot;設定ファイル (pack.json)&quot;">​</a></h3><p>これは MOD がサウンドパックを認識するための重要なファイルです。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;displayName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My Sound Pack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;available_instruments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">54</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">66</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">72</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 楽器0が持っているサンプリング音程のリスト</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><em>注意：通常はオーディオファイルを配置して「更新」をクリックするだけで、MOD が自動的にこのファイルを更新します。</em></p><h2 id="なぜサウンドパックを使用するのか" tabindex="-1">なぜサウンドパックを使用するのか？ <a class="header-anchor" href="#なぜサウンドパックを使用するのか" aria-label="Permalink to &quot;なぜサウンドパックを使用するのか？&quot;">​</a></h2><ul><li><strong>無限の拡張性</strong>: 命名規則に従ってサンプルを配置すれば、ゲーム内で実際にあらゆる楽器の音を演奏できます。</li><li><strong>スマートマッピング</strong>: すべての音程のサンプルを録音する必要はありません。MOD は録音されていない音符を最も近い利用可能なサンプルに自動的にマッピングし、音程を調整して再生します。</li><li><strong>高い互換性</strong>: 標準的なリソースパックであるため、通常のリソースパック（テクスチャパック）と同じようにサウンドパックを配布できます。</li></ul>`,28)])])}const m=n(o,[["render",p]]);export{E as __pageData,m as default};
